A.bXM=new B.jD("Breaker off, then test","Before you touch any wire, switch its breaker OFF, then check with a voltage tester that the wire is dead. A switch on the wall is not enough.")
A.bXz=new B.jD("Lock out, tag out","On a real job you put a lock or a note on the panel so nobody switches the power back on while you work.")
A.bXT=new B.jD("Water and power","Water carries electricity. Near sinks, tubs and outdoors the outlets must be GFCI, and wet hands never touch wires.")
A.bXE=new B.jD("Eyes, ears, lungs","Safety glasses for drilling and cutting, ear protection for loud tools, and a mask when you sand drywall dust or cut tile.")
A.bXS=new B.jD("Shut the water off","Before you cut or loosen a pipe, close the main water valve and open a faucet to drain the line.")
A.deR=w([A.bXM,A.bXz,A.bXT,A.bXE,A.bXS],x.Z)
A.bY4=new B.ML("Safety first","\ud83e\uddba",D.cs,A.deR)
A.bXU=new B.jD("Wire colours","Black is hot (it carries the power), white is neutral (the way back), bare copper or green is ground (the safety path). Red is a second hot, often used for a switched line.")
A.bY0=new B.jD("Screw colours","On an outlet the brass screw takes the hot wire, the silver screw takes the neutral and the green screw takes the ground.")
A.bXO=new B.jD("Wire size","14 gauge wire is for 15 amp circuits (lights and outlets). 12 gauge is for 20 amp circuits (kitchens). A thinner wire than the breaker allows can overheat and start a fire.")
A.bXI=new B.jD("Breakers","A breaker is a safety switch. It trips when a circuit carries too much current, so the wires never get hot enough to burn.")
A.bXW=new B.jD("Wire nuts","Strip about 3/4 inch, twist the bare ends together clockwise, and screw on the nut until no bare copper shows. Give each wire a gentle tug.")
A.bY1=new B.jD("Switches","A switch cuts the hot wire only. The neutral goes straight through to the light.")
A.bY2=new B.jD("GFCI","A GFCI outlet watches the current going out and coming back. If a little leaks (through water or a person) it cuts the power in a fraction of a second.")
A.bXB=new B.jD("Ceiling fans","A fan shakes and is heavy. It needs a box that says fan rated, fixed to the joist, not a plain light box.")
A.bXD=new B.jD("Heights","Outlets sit about 16 inches from the floor. Switches sit about 48 inches up, where your hand falls.")
