A.bXC=new B.jD("Studs","Studs are the vertical 2x4 posts inside a wall, 16 inches apart from centre to centre. Everything is fixed to them.")
A.bXQ=new B.jD("Drilling studs","Holes for cable go through the middle of the stud, so a nail or screw cannot reach the wire.")
A.bXH=new B.jD("Drywall","A sheet is 4 feet wide, so its edges land on studs 48 inches apart. Screws go into studs only, just under the paper.")
A.bXK=new B.jD("Taping and mud","Seams get paper tape and three thin coats of joint compound, sanded smooth between coats, then primer and paint.")
A.bXZ=new B.jD("Order of a build","Frame, run the pipes and wires (rough-in), inspect, hang drywall, finish it, paint, then fit the fixtures and devices.")
