A.bXL=new B.jD("Voltage tester","A pen that glows or beeps near live wires. Test it on a known live outlet first, so you know it works.")
A.bXR=new B.jD("Wire strippers","Strip the plastic off without nicking the copper. A nick weakens the wire.")
A.bXX=new B.jD("Adjustable wrench","For nuts on valves and hoses. Hold the fitting steady with a second wrench so you do not twist the pipe.")
A.bXP=new B.jD("Drill and screw gun","A drill makes holes through studs. A screw gun sets drywall screws to the right depth.")
